RELEVANT_IDS [{"id": "human-medicine-largest-organ", "topicId": "human-medicine", "sourceOrder": 1, "card": {"id": "human-medicine-largest-organ", "difficulty": "easy", "prompt": "Какой орган обычно называют крупнейшим органом тела человека?", "answers": [{"text": "Кожа", "note": "Кожа — крупнейший орган человеческого тела."}, {"text": "Печень", "note": "Печень обезвреживает вещества, синтезирует белки плазмы и производит желчь."}, {"text": "Тонкая кишка", "note": "Тонкая кишка — основной участок переваривания и всасывания питательных веществ."}, {"text": "Лёгкие", "note": "Лёгкие обеспечивают газообмен между воздухом и кровью."}], "correctIndex": 0, "explanation": "Кожа — крупнейший орган человеческого тела. Она образует внешний защитный покров и участвует в терморегуляции, чувствительности и синтезе витамина D.", "source": {"title": "NCBI Bookshelf: How Does Skin Work?", "url": "https://www.ncbi.nlm.nih.gov/books/NBK279255/", "verifiedAt": "2026-09-02"}}, "sha256": "91e1d931fbf85cbea24dbc36a1e5d11389c503e532a45b63fdef76cde5431755"}, {"id": "human-medicine-bile-production", "topicId": "human-medicine", "sourceOrder": 13, "card": {"id": "human-medicine-bile-production", "difficulty": "easy", "prompt": "Какой орган вырабатывает желчь?", "answers": [{"text": "Печень", "note": "Желчь вырабатывается клетками печени и помогает эмульгировать жиры в тонкой кишке."}, {"text": "Желчный пузырь", "note": "Желчный пузырь накапливает и концентрирует желчь."}, {"text": "Поджелудочная железа", "note": "Поджелудочная железа выделяет пищеварительные ферменты и гормоны."}, {"text": "Селезёнка", "note": "Селезёнка фильтрует кровь и участвует в иммунных реакциях."}], "correctIndex": 0, "explanation": "Желчь вырабатывается клетками печени и помогает эмульгировать жиры в тонкой кишке. Желчный пузырь главным образом накапливает и концентрирует желчь между приёмами пищи.", "source": {"title": "OpenStax Anatomy and Physiology 2e: The Liver, Pancreas, and Gallbladder", "url": "https://openstax.org/books/anatomy-and-physiology-2e/pages/23-6-accessory-organs-in-digestion-the-liver-pancreas-and-gallbladder", "verifiedAt": "2026-10-23"}}, "sha256": "5c2395f692066c060a60e7523d90bd20ca70ca8c7dac6ae4d00626ac104ada8e"}, {"id": "human-medicine-largest-internal-organ", "topicId": "human-medicine", "sourceOrder": 34, "card": {"id": "human-medicine-largest-internal-organ", "difficulty": "easy", "prompt": "Какой орган является крупнейшим внутренним органом человека?", "answers": [{"text": "Сердце", "note": "Сердце — мышечный орган, перекачивающий кровь по сосудам."}, {"text": "Печень", "note": "Печень — крупнейший внутренний орган человека."}, {"text": "Почка", "note": "Почка фильтрует кровь, регулирует водно-солевой баланс и образует мочу."}, {"text": "Селезёнка", "note": "Селезёнка фильтрует кровь и участвует в иммунных реакциях."}], "correctIndex": 1, "explanation": "Печень — крупнейший внутренний орган человека. Она участвует в обмене веществ, обезвреживании соединений и образовании желчи.", "source": {"title": "NCBI Bookshelf: Liver Anatomy", "url": "https://www.ncbi.nlm.nih.gov/books/NBK535438/", "verifiedAt": "2026-09-02"}}, "sha256": "e42158edfb67242322eab5d63d694c709233692703c5cf141d3fa096f0fa56bf"}]
